MACRO_PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>股债性价比与成长/红利风格</title>
<style>
:root{--ink:#182230;--muted:#667085;--line:#e1e7f0;--blue:#155eef;--blue-bg:#f0f6ff;--green:#027a48;--green-bg:#ecfdf3;--amber:#b54708;--amber-bg:#fffaeb;--red:#b42318;--red-bg:#fef3f2}*{box-sizing:border-box}body{font-family:system-ui,"Microsoft YaHei",sans-serif;background:#f5f7fb;color:var(--ink);margin:0}.wrap{max-width:1280px;margin:auto;padding:28px}nav[aria-label="监控模式"]{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px}nav[aria-label="监控模式"] a{color:#2457a6;text-decoration:none;font-weight:600;border:1px solid #d5deeb;border-radius:999px;padding:6px 12px;background:#fff}.hero,.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:0 5px 18px #1f3b5d0d}.hero{border-top:4px solid var(--blue)}.hero h1{margin:0 0 8px}.hero p{line-height:1.65}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.headline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px 28px;margin-bottom:16px}.headline.wide{grid-template-columns:repeat(4,minmax(0,1fr))}.metric{font-size:30px;font-weight:700;color:var(--blue);line-height:1.2;font-variant-numeric:tabular-nums}.sub,.note{font-size:13px;color:var(--muted);line-height:1.5}.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px 20px;padding-top:14px;border-top:1px solid #edf0f5}.fact-value{font-size:17px;font-weight:650;margin-top:4px}.note{margin:0 0 14px}.callout{padding:12px 14px;border-radius:10px;background:var(--blue-bg);border:1px solid #cfe0ff;line-height:1.6}.callout.warn{background:var(--amber-bg);border-color:#fedf89}.status-line{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:14px}.status-title{font-size:20px;font-weight:700}.pill{padding:4px 9px;border-radius:99px;font-size:12px;font-weight:650;white-space:nowrap}.tier-VERY_CHEAP,.tier-GROWTH_WEAK{background:var(--green-bg);color:var(--green)}.tier-CHEAP,.tier-GROWTH_FAVORED{background:#eef4ff;color:#175cd3}.tier-NEUTRAL{background:#f2f4f7;color:#344054}.tier-RICH,.tier-GROWTH_WARM{background:var(--amber-bg);color:var(--amber)}.tier-VERY_RICH,.tier-GROWTH_HOT{background:var(--red-bg);color:var(--red)}.tier-UNAVAILABLE{background:#f8fafc;color:var(--muted)}.warn{color:var(--amber)}.bad{color:var(--red)}.good{color:var(--green)}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.table-wrap{overflow-x:auto}table{width:100%;min-width:720px;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #edf0f5;vertical-align:top;line-height:1.45}th{background:#f8fafc;white-space:nowrap}tr.current th,tr.current td{background:#f0f6ff}.now{display:inline-block;margin-right:8px;color:var(--blue);font-size:12px;font-weight:700}.empty{padding:14px;border-radius:9px;background:#f8fafc;color:var(--muted)}.legend{font-size:12px;color:var(--muted);margin:8px 0 0}@media(max-width:850px){.wrap{padding:16px}.two{grid-template-columns:1fr}.headline,.headline.wide{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.headline,.headline.wide{grid-template-columns:1fr}.hero,.card{padding:16px}}
</style></head>
<body><main class="wrap"><nav aria-label="监控模式"><a href="/swing">波段监控</a><a href="/">做T监控</a><a href="/pr">PR估值</a><a href="/macro" aria-current="page">股债与风格</a><a href="/notifications">通知中心</a></nav>
<section class="hero"><h1>股债性价比与成长/红利风格</h1><p class="muted">这是一页只读的宏观观察面板：<b>ERP 只用于观察总量环境</b>，成长/红利比值只用于观察新增资金的风格倾向。它不代表个人账户目标仓位，不改变正式策略，也不产生下单、调仓或通知。</p><div class="callout"><b>阅读顺序：</b>先看当前状态与数据截止日，再看 ERP 的“盈利收益率 − 国债收益率”分解，最后看成长/红利相对强弱是否出现趋势确认。</div></section>
<section class="card"><h2>当前状态</h2><div id="combined"><div class="empty">加载中</div></div></section>
<div class="two"><section class="card"><h2>指标一：股债性价比（ERP）</h2><p class="note">ERP = 100 ÷ 沪深300 PE-TTM − 10年期国债收益率。分位越高代表历史上相对更有吸引力，但低利率也会机械抬高 ERP，因此页面单独展示利率修正。</p><div id="erp" class="grid"></div><div id="erp-tiers"></div></section>
<section class="card"><h2>指标二：成长 / 红利 ETF 相对强弱</h2><p class="note">比值 = 创业板ETF 159915 ÷ 中证红利ETF 515180 的复权序列；这是两个 ETF 的相对表现，不是两个指数估值比，也不是未来收益预测。</p><div id="style" class="grid"></div><div id="style-tiers"></div></section></div>
<section class="card"><h2>组合矩阵：先看总量，再看风格</h2><p class="note">矩阵中的“模型参考权益比例”是指标档位映射，不是个人账户建议；“降低新增权益”表示研究含义，不等于系统自动卖出。</p><div class="table-wrap"><table><thead><tr><th>ERP ＼ 比值</th><th>&lt; 30%（偏成长）</th><th>30%~70%（中性）</th><th>&gt; 70%（偏红利）</th></tr></thead><tbody id="matrix"><tr data-row="ADD"><th>&gt; 70%（便宜）</th><td data-col="GROWTH">增加新增权益，风格偏成长</td><td data-col="BALANCED">增加新增权益，按原比例观察</td><td data-col="DIVIDEND">增加新增权益，风格偏红利</td></tr><tr data-row="HOLD"><th>30%~70%（中性）</th><td data-col="GROWTH">按计划，新增资金成长 1.2×</td><td data-col="BALANCED">按计划，维持观察</td><td data-col="DIVIDEND">按计划，新增资金红利 1.1×</td></tr><tr data-row="REDUCE"><th>&lt; 30%（偏贵）</th><td data-col="GROWTH">降低新增权益，优先保留相对强势风格</td><td data-col="BALANCED">降低新增权益，按比例观察</td><td data-col="DIVIDEND">降低新增权益，优先保留相对强势风格</td></tr></tbody></table></div></section>
<section class="card"><h2>数据来源、覆盖与健康状态</h2><div id="coverage" class="muted">加载中</div></section></main>
<script>
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=(v,d=2)=>v==null||v===''?'—':Number(v).toFixed(d);
const pill=(tier,label)=>'<span class="pill tier-'+esc(tier||'UNAVAILABLE')+'">'+esc(label||'不可用')+'</span>';
const TIER_NAME={VERY_CHEAP:'极度便宜',CHEAP:'偏便宜',NEUTRAL:'中性',RICH:'偏贵',VERY_RICH:'极贵',GROWTH_HOT:'成长过热',GROWTH_WARM:'成长偏热',GROWTH_FAVORED:'偏向成长',GROWTH_WEAK:'成长极弱'};
const tierName=key=>TIER_NAME[key]||key||'—';
const lead=(k,v,sub)=>'<div><div class="muted">'+esc(k)+'</div><div class="metric">'+v+'</div>'+(sub?'<div class="sub">'+sub+'</div>':'')+'</div>';
const fact=(k,v,sub)=>'<div><div class="muted">'+esc(k)+'</div><div class="fact-value">'+v+'</div>'+(sub?'<div class="sub">'+esc(sub)+'</div>':'')+'</div>';
const unavailable=x=>'<div class="empty">指标不可用：'+esc(x.reason||'未知')+(x.sample_days!=null?'（样本 '+esc(x.sample_days)+' / 需 '+esc(x.minimum_days)+' 日）':'')+'</div>';
function erpView(x){if(x.status!=='OK')return unavailable(x);const band=(x.adopted_percentile_low==null?'—':fmt(x.adopted_percentile_low,0)+'–'+fmt(x.adopted_percentile_high,0)+'%');const note=x.rate_driven?'触发利率修正：ERP分位比 PE 便宜度高 '+fmt(x.rate_correction_gap,1)+' 个百分点，超过阈值15；原档「'+esc(tierName(x.raw_tier))+'」下调一档。':'未触发利率修正：ERP分位与 PE 便宜度的差值未超过15个百分点。';return '<div class="status-line"><span class="status-title">'+esc(x.action)+'</span>'+pill(x.tier,x.tier_label)+'</div><div class="headline">'+lead('模型参考权益比例',esc(x.equity_target_pct)+'%','仅为档位映射，不是个人仓位')+lead('采用分位区间',band,'10年分位经利率修正后的档位')+lead('定投倍数',fmt(x.dca_multiplier,1)+'×','相对基础节奏')+'</div><div class="facts">'+fact('ERP',fmt(x.erp_pct)+'%','盈利收益率 '+fmt(x.earnings_yield_pct,2)+'% − 国债 '+fmt(x.cn10y_yield_pct,3)+'%')+fact('沪深300 PE-TTM',fmt(x.pe_ttm),'PE分位 '+fmt(x.pe_percentile,1)+'%，便宜度 '+fmt(x.pe_cheapness_percentile,1)+'%')+fact('10年期国债',fmt(x.cn10y_yield_pct,3)+'%',x.cn10y_as_of)+fact('历史分位',fmt(x.erp_percentile_10y,1)+'%','5年 '+fmt(x.erp_percentile_5y,1)+'% · 3年 '+fmt(x.erp_percentile_3y,1)+'%')+fact('数据截止',x.as_of,'样本 '+esc(x.sample_days)+' 日，起始 '+esc(x.sample_start))+'</div><p class="note">'+note+'</p>'}
function styleView(x){if(x.status!=='OK')return unavailable(x);const trendName=!x.above_ma20&&x.ma20_falling?'转弱':!x.above_ma20?'跌破20日均线':x.ma20_falling?'均线向下':'均线之上';const switchText=x.switch_confirmed?'<span class="bad">已满足</span>':'未触发';const direction=x.ratio_vs_ma20_pct==null?'—':(x.ratio_vs_ma20_pct>=0?'+':'')+fmt(x.ratio_vs_ma20_pct,2)+'%';return '<div class="status-line"><span class="status-title">'+esc(trendName)+'</span>'+pill(x.tier,x.tier_label)+'</div><div class="headline wide">'+lead('当前3年分位',fmt(x.ratio_percentile,1)+'%','比值 '+fmt(x.ratio_normalized,3)+'（起点=1）')+lead('比值相对MA20',direction,'正值在均线上方，负值在均线下方')+lead('成长新增倍数',fmt(x.growth_multiplier,1)+'×','不是存量调仓')+lead('红利新增倍数',fmt(x.dividend_multiplier,1)+'×','不是存量调仓')+'</div><div class="facts">'+fact('MA20',fmt(x.ratio_ma20,3),x.ma20_falling?'均线向下':'均线未向下')+fact('20日变化',(x.ratio_change_20d_pct>=0?'+':'')+fmt(x.ratio_change_20d_pct,2)+'%','短期相对强弱')+fact('约60日变化',(x.ratio_change_60d_pct>=0?'+':'')+fmt(x.ratio_change_60d_pct,2)+'%','中期相对强弱')+fact('MA20斜率',(x.ma20_slope_pct>=0?'+':'')+fmt(x.ma20_slope_pct,2)+'%','前后两个20日均值比较')+fact('存量切换确认',switchText,esc(x.switch_rule))+fact('数据截止',x.as_of,'样本 '+esc(x.sample_days)+' 日，起始 '+esc(x.sample_start))+'</div><p class="note">高位只降低新增；只有比值跌破20日均线且均线向下，才满足成长过热档的存量切换条件。</p>'}
function tiers(rows,current,cols){return '<div class="table-wrap"><table><thead><tr><th>分位下限</th><th>档位</th>'+cols.map(c=>'<th>'+esc(c[0])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr'+(r.tier===current?' class="current"':'')+'><td>'+(r.tier===current?'<span class="now">当前</span>':'')+'≥ '+esc(r.min_percentile)+'%</td><td>'+pill(r.tier,r.label)+'</td>'+cols.map(c=>'<td>'+esc(c[1](r))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
async function load(){const r=await fetch('/api/macro');if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();const erp=d.erp||{},st=d.style_ratio||{},c=d.combined||{};const when=String(d.generated_at||'').replace('T',' ').replace('+08:00','');document.querySelector('#combined').innerHTML=c.status==='OK'?'<div class="headline wide">'+lead('当前研究状态',esc(c.summary),esc(c.total_action==='ADD'?'总量偏增加新增权益':c.total_action==='REDUCE'?'总量偏降低新增权益':'总量按计划观察'))+lead('ERP模型参考比例',erp.equity_target_pct==null?'—':esc(erp.equity_target_pct)+'%','不等同于个人账户仓位')+lead('成长新增倍数',fmt(c.growth_multiplier,1)+'×','由风格比值决定')+lead('红利新增倍数',fmt(c.dividend_multiplier,1)+'×','由风格比值决定')+'</div><div class="callout warn"><b>信号边界：</b>当前结论只描述模型状态，不能替代持仓核实、风险承受能力、费用与执行窗口判断。生成时间 '+esc(when)+'；页面只读，不下单。</div>':'<div class="empty">任一指标不可用时不给出综合结论。</div>';document.querySelector('#erp').innerHTML=erpView(erp);document.querySelector('#style').innerHTML=styleView(st);document.querySelector('#erp-tiers').innerHTML=tiers(d.erp_tiers||[],erp.tier,[['模型参考比例',r=>r.equity_target_pct+'%'],['定投倍数',r=>r.dca_multiplier+'×'],['研究含义',r=>r.action]]);document.querySelector('#style-tiers').innerHTML=tiers(d.style_tiers||[],st.tier,[['成长新增',r=>r.growth_multiplier+'×'],['红利新增',r=>r.dividend_multiplier+'×'],['存量切换规则',r=>r.switch_rule]]);if(c.status==='OK'){const td=document.querySelector('#matrix tr[data-row="'+c.total_action+'"] td[data-col="'+c.style_lean+'"]');if(td){td.style.background='#f0f6ff';td.style.fontWeight='700'}}const cov=d.series_coverage||{},errs=d.errors||{};const line=(name,k,src)=>'<p><b>'+esc(name)+'</b>：'+esc(src)+'；已存 '+esc(cov[k]?.count??0)+' 日（'+esc(cov[k]?.start??'—')+' ~ '+esc(cov[k]?.end??'—')+'）'+(errs[k]?' <span class="bad">最近刷新失败：'+esc(errs[k])+'</span>':'')+'</p>';document.querySelector('#coverage').innerHTML=line('10年期国债收益率','CN10Y','东方财富数据中心 RPTA_WEB_TREASURYYIELD，字段 EMM00166466，日频，含非交易日')+line('沪深300 PE-TTM','CSI300_PE_TTM','中证指数公司 index-perf 的 peg 字段（滚动市盈率），日频，按自然年分段抓取')+'<p><b>风格比值</b>：仓库已核验的 ETF 复权日线（创业板ETF 159915 ÷ 中证红利ETF 515180），用于相对强弱观察。'+(errs.history?' <span class="bad">读取失败：'+esc(errs.history)+'</span>':'')+'</p><p class="muted">外部序列每小时最多刷新一次；刷新失败沿用已存数据并在此处标注。数据截止日以各指标卡片为准。</p>'}
load().catch(e=>{document.querySelector('#combined').innerHTML='<div class="empty bad">接口暂不可用：'+esc(e.message)+'</div>'});
</script></body></html>'''
